import useEmblaCarousel, {
    type UseEmblaCarouselType,
} from 'embla-carousel-react';
import { ArrowLeft, ArrowRight } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import {
    elevatedSurface,
    nestedRadius,
    nestedSurfaceReset,
} from '@/lib/language';
import { cn } from '@/lib/utils';
import { useUiLabels } from '@/locales/context';
import type { SlotNameProps } from '@/types';

export interface CarouselLabels {
    carouselLabel: string;
    slideLabel: string;
    previousLabel: string;
    nextLabel: string;
}

export const carouselDefaultLabels: CarouselLabels = {
    carouselLabel: 'carousel',
    slideLabel: 'slide',
    previousLabel: 'Previous slide',
    nextLabel: 'Next slide',
};

type CarouselApi = UseEmblaCarouselType[1];
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>;
type CarouselOptions = UseCarouselParameters[0];
type CarouselPlugin = UseCarouselParameters[1];

type CarouselProps = {
    opts?: CarouselOptions;
    plugins?: CarouselPlugin;
    orientation?: 'horizontal' | 'vertical';
    setApi?: (api: CarouselApi) => void;
};

type CarouselContextProps = {
    carouselRef: ReturnType<typeof useEmblaCarousel>[0];
    api: ReturnType<typeof useEmblaCarousel>[1];
    scrollPrev: () => void;
    scrollNext: () => void;
    canScrollPrev: boolean;
    canScrollNext: boolean;
} & CarouselProps;

const CarouselContext = React.createContext<CarouselContextProps | null>(null);

function useCarousel() {
    const context = React.useContext(CarouselContext);

    if (!context) {
        throw new Error('useCarousel must be used within a <Carousel />');
    }

    return context;
}

function Carousel({
    orientation = 'horizontal',
    opts,
    setApi,
    plugins,
    className,
    children,
    slotName = 'carousel',
    ...props
}: React.ComponentProps<'div'> & CarouselProps & SlotNameProps) {
    const labels = useUiLabels('carousel', carouselDefaultLabels);
    const [carouselRef, api] = useEmblaCarousel(
        {
            ...opts,
            axis: orientation === 'horizontal' ? 'x' : 'y',
        },
        plugins,
    );
    const [canScrollPrev, setCanScrollPrev] = React.useState(false);
    const [canScrollNext, setCanScrollNext] = React.useState(false);

    const onSelect = React.useCallback((api: CarouselApi) => {
        if (!api) return;
        setCanScrollPrev(api.canScrollPrev());
        setCanScrollNext(api.canScrollNext());
    }, []);

    const scrollPrev = React.useCallback(() => {
        api?.scrollPrev();
    }, [api]);

    const scrollNext = React.useCallback(() => {
        api?.scrollNext();
    }, [api]);

    const handleKeyDown = React.useCallback(
        (event: React.KeyboardEvent<HTMLDivElement>) => {
            if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') {
                return;
            }

            event.preventDefault();

            if (event.key === 'ArrowLeft') {
                scrollPrev();
                return;
            }

            scrollNext();
        },
        [scrollPrev, scrollNext],
    );

    React.useEffect(() => {
        if (!api || !setApi) return;
        setApi(api);
    }, [api, setApi]);

    React.useEffect(() => {
        if (!api) return;
        onSelect(api);
        api.on('reInit', onSelect);
        api.on('select', onSelect);

        return () => {
            api?.off('select', onSelect);
        };
    }, [api, onSelect]);

    return (
        <CarouselContext.Provider
            value={{
                carouselRef,
                api: api,
                opts,
                orientation:
                    orientation ||
                    (opts?.axis === 'y' ? 'vertical' : 'horizontal'),
                scrollPrev,
                scrollNext,
                canScrollPrev,
                canScrollNext,
            }}
        >
            <div
                onKeyDownCapture={handleKeyDown}
                className={cn(
                    elevatedSurface,
                    nestedSurfaceReset,
                    'p-4 relative bg-card',
                    className,
                )}
                role="region"
                aria-roledescription={labels.carouselLabel}
                {...props}
                data-slot={slotName}
            >
                {children}
            </div>
        </CarouselContext.Provider>
    );
}

function CarouselContent({
    className,
    slotName = 'carousel-content',
    ...props
}: React.ComponentProps<'div'> & SlotNameProps) {
    const { carouselRef, orientation } = useCarousel();

    return (
        <div
            ref={carouselRef}
            className={cn(nestedRadius, 'overflow-hidden')}
            data-slot={slotName}
        >
            <div
                className={cn(
                    'flex',
                    orientation === 'horizontal' ? '-ml-4' : '-mt-4 flex-col',
                    className,
                )}
                {...props}
            />
        </div>
    );
}

function CarouselItem({
    className,
    slotName = 'carousel-item',
    ...props
}: React.ComponentProps<'div'> & SlotNameProps) {
    const { orientation } = useCarousel();
    const labels = useUiLabels('carousel', carouselDefaultLabels);

    return (
        <div
            role="group"
            aria-roledescription={labels.slideLabel}
            className={cn(
                'min-w-0 shrink-0 grow-0 basis-full',
                orientation === 'horizontal' ? 'pl-4' : 'pt-4',
                className,
            )}
            {...props}
            data-slot={slotName}
        />
    );
}

function CarouselPrevious({
    className,
    variant = 'outline',
    size = 'icon',
    label,
    slotName = 'carousel-previous',
    ...props
}: React.ComponentProps<typeof Button> & { label?: string } & SlotNameProps) {
    const { orientation, scrollPrev, canScrollPrev } = useCarousel();
    const labels = useUiLabels('carousel', carouselDefaultLabels, {
        previousLabel: label,
    });

    return (
        <Button
            variant={variant}
            size={size}
            className={cn(
                'size-9 absolute rounded-full',
                orientation === 'horizontal'
                    ? '-left-12 top-1/2 -translate-y-1/2'
                    : '-top-12 left-1/2 -translate-x-1/2 rotate-90',
                className,
            )}
            disabled={!canScrollPrev}
            onClick={scrollPrev}
            {...props}
            slotName={slotName}
        >
            <ArrowLeft />
            <span className="sr-only">{labels.previousLabel}</span>
        </Button>
    );
}

function CarouselNext({
    className,
    variant = 'outline',
    size = 'icon',
    label,
    slotName = 'carousel-next',
    ...props
}: React.ComponentProps<typeof Button> & { label?: string } & SlotNameProps) {
    const { orientation, scrollNext, canScrollNext } = useCarousel();
    const labels = useUiLabels('carousel', carouselDefaultLabels, {
        nextLabel: label,
    });

    return (
        <Button
            variant={variant}
            size={size}
            className={cn(
                'size-9 absolute rounded-full',
                orientation === 'horizontal'
                    ? '-right-12 top-1/2 -translate-y-1/2'
                    : '-bottom-12 left-1/2 -translate-x-1/2 rotate-90',
                className,
            )}
            disabled={!canScrollNext}
            onClick={scrollNext}
            {...props}
            slotName={slotName}
        >
            <ArrowRight />
            <span className="sr-only">{labels.nextLabel}</span>
        </Button>
    );
}

export {
    Carousel,
    CarouselContent,
    CarouselItem,
    CarouselNext,
    CarouselPrevious,
    type CarouselApi,
};
