import {
    CircleCheckIcon,
    InfoIcon,
    Loader2Icon,
    OctagonXIcon,
    TriangleAlertIcon,
} from 'lucide-react';
import { useEffect, useState } from 'react';
import { Toaster as Sonner, type ToasterProps } from 'sonner';

import {
    toastActionClasses,
    toastCancelClasses,
    toastCloseClasses,
} from '@/lib/toast-classes';

function useDocumentScheme(): 'light' | 'dark' {
    const [scheme, setScheme] = useState<'light' | 'dark'>('light');

    useEffect(() => {
        const root = document.documentElement;
        const read = () =>
            setScheme(root.classList.contains('dark') ? 'dark' : 'light');

        read();

        const observer = new MutationObserver(read);
        observer.observe(root, {
            attributes: true,
            attributeFilter: ['class'],
        });

        return () => observer.disconnect();
    }, []);

    return scheme;
}

const Toaster = ({
    theme,
    closeButton = true,
    toastOptions,
    ...props
}: ToasterProps) => {
    const scheme = useDocumentScheme();

    return (
        <Sonner
            theme={theme ?? scheme}
            closeButton={closeButton}
            toastOptions={{
                ...toastOptions,
                classNames: {
                    actionButton: toastActionClasses,
                    cancelButton: toastCancelClasses,
                    closeButton: toastCloseClasses,
                    ...toastOptions?.classNames,
                },
            }}
            className="toaster group [&_[data-sonner-toast]]:shadow-2xl [&_[data-sonner-toast]]:backdrop-blur-xl"
            icons={{
                success: <CircleCheckIcon className="size-4" />,
                info: <InfoIcon className="size-4" />,
                warning: <TriangleAlertIcon className="size-4" />,
                error: <OctagonXIcon className="size-4" />,
                loading: <Loader2Icon className="size-4 animate-spin" />,
            }}
            style={
                {
                    '--normal-bg':
                        'color-mix(in oklab, var(--popover) 90%, transparent)',
                    '--normal-text': 'var(--popover-foreground)',
                    '--normal-border': 'var(--border)',
                    '--border-radius': '1rem',
                } as React.CSSProperties
            }
            {...props}
        />
    );
};

export { Toaster };
